def feedback(lang):
 def t(zh,en):return zh if lang=='zh' else en
 base='https://github.com/JuneLeGency/orbit-site/issues'
 return f'''<section class="section feedback-section" id="feedback"><div><p class="eyebrow">HELP IMPROVE ORBIT</p><h2>{t('遇到问题，告诉我们。','Found a problem? Let us know.')}</h2><p>{t('应用打不开、阿洛操作不顺，或想要一个新功能，都可以在 GitHub 留下反馈。提交前也可以看看是否已有相关讨论。','An app won’t open, Alo gets stuck, or you have an idea for a feature? Share it on GitHub, or check existing reports first.')}</p></div><div class="feedback-actions"><a class="button primary" href="{base}/new?template=bug_report.yml">{t('反馈问题','Report a bug')}</a><a class="button" href="{base}/new?template=feature_request.yml">{t('建议新功能','Suggest a feature')}</a><a class="text-link" href="{base}">{t('查看已有反馈','Browse existing feedback')}</a></div><p class="feedback-note">{t('提交需要 GitHub 账号，反馈公开可见。模板会引导你填写设备、版本和复现步骤；不便公开的内容请联系','A GitHub account is required to submit; reports are public. The form asks for device details, versions and reproduction steps. For private reports, contact')} <a href="mailto:miioflee@gmail.com">miioflee@gmail.com</a>{t("。",".")}</p></section>'''
